const cfg = $('Carica prompt e contratto').first().json;
const task = `${cfg.contratto_comune}

${cfg.prompt}

Titolo incarico: ${cfg.titolo}

Per ogni notizia produci una sola riga nel formato esatto: NEWS: titolo | FACT: fatto verificato | URL: https://... | WHY: perché conta. Massimo tre righe. Includi solo notizie con URL diretto verificabile. Se non ci sono novità, scrivi esattamente: NESSUN AGGIORNAMENTO — nessuna azione richiesta. Non aggiungere preamboli o blocchi di codice.`;
return [{json:{model:'ai-standard',input:task}}];

const r = $json;
const blocks = Array.isArray(r.output) ? r.output.flatMap(o => Array.isArray(o.content) ? o.content : []) : [];
const text = blocks.filter(c => typeof c.text === "string").map(c => c.text).join("\n").trim() || (typeof r.output_text === "string" ? r.output_text.trim() : "");
if (!text) throw new Error("LiteLLM did not return briefing text");
const citations = [...new Set(blocks.flatMap(c => Array.isArray(c.annotations) ? c.annotations : []).filter(a => a.type === "url_citation" && a.url).map(a => a.url))];
function canonicalUrl(value) {
  try {
    const url = new URL(value);
    url.hash = "";
    for (const key of [...url.searchParams.keys()]) if (/^(utm_|ref$|source$)/i.test(key)) url.searchParams.delete(key);
    url.pathname = url.pathname.replace(/\/$/, "");
    url.hostname = url.hostname.toLowerCase();
    const parameters = [...url.searchParams.entries()].sort(([a], [b]) => a.localeCompare(b));
    url.search = "";
    for (const [key, item] of parameters) url.searchParams.append(key, item);
    return url.toString();
  } catch {
    return value;
  }
}
function tokens(value) {
  return value.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9 ]/g, " ").split(/\s+/).filter(t => t.length > 2 && !["the","and","for","with","from","that","this","della","delle","degli","dell","che","per","una","uno","nel","nella","alla","alle","con","come","dopo","sul","sulla","tra","fra"].includes(t));
}
const candidatePattern = /^\s*(?:[-*]\s*)?NEWS:\s*(.+?)\s*\|\s*FACT:\s*(.+?)\s*\|\s*URL:\s*(https?:\/\/\S+?)\s*\|\s*WHY:\s*(.+?)\s*$/gm;
const postedPattern = /^• \*(.+?)\* — (.+?)\n  <([^>|]+)\|Fonte>\n  _Perché conta: (.+?)_$/gm;
function parseCandidateRecords(value) {
  return [...value.matchAll(candidatePattern)].map(m => ({title:m[1].trim(),fact:m[2].trim(),url:m[3].replace(/[),.;]+$/, ""),why:m[4].trim()}));
}
function parsePublishedRecords(value) {
  return [...value.matchAll(postedPattern)].map(m => ({title:m[1].trim(),fact:m[2].trim(),url:m[3].trim(),why:m[4].trim()}));
}
const candidates = parseCandidateRecords(text);
const explicitNoUpdates = /NESSUN AGGIORNAMENTO/i.test(text);
if (!explicitNoUpdates && candidates.length === 0) throw new Error("LiteLLM did not follow NEWS/FACT/URL/WHY format");
const verifiedUrls = new Set(citations.map(canonicalUrl));
if (candidates.some(item => !verifiedUrls.has(canonicalUrl(item.url)))) throw new Error("Briefing item URL is missing a web_search URL citation");
const marker = "_Briefing tech quotidiano · ref:daily-tech-briefing_";
const priorMessages = $("Leggi storico del canale").all().map(i => i.json).filter(m => m.user === "U0BP05KJACA" && typeof m.text === "string" && m.text.includes(marker));
const previous = priorMessages.flatMap(m => parsePublishedRecords(m.text));
const seenUrls = new Set(previous.map(item => canonicalUrl(item.url)));
const seenTitles = previous.map(item => new Set(tokens(item.title + " " + item.fact)));
const fresh = candidates.filter(item => {
  const url = canonicalUrl(item.url);
  const words = new Set(tokens(item.title + " " + item.fact));
  const duplicate = seenUrls.has(url) || seenTitles.some(old => {
    const union = new Set([...old, ...words]);
    const overlap = [...words].filter(word => old.has(word)).length;
    return union.size > 0 && overlap / union.size >= 0.6;
  });
  if (duplicate) return false;
  seenUrls.add(url);
  seenTitles.push(words);
  return true;
});
let lines;
if (explicitNoUpdates || fresh.length === 0) {
  lines = ["NESSUN AGGIORNAMENTO — nessuna azione richiesta"];
} else {
  lines = fresh.slice(0, 3).map(item => "• *" + item.title + "* — " + item.fact + "\n  <" + item.url + "|Fonte>\n  _Perché conta: " + item.why + "_");
}
const report = [...lines, marker].join("\n\n");
return [{json:{report,priorBriefingCount:previous.length,deduplicatedCount:candidates.length-fresh.length}}];
